907,2983,8000,7166,9666,6666,8333,8000,8000,"jiuchaoyan_2"},h)g[405201]=b({e[46059],405201,false,129,280,false,200052,false,"deco/character/405201",302002,60,false,false,false,false,-110,"1",false,false,false,false,false,false,false,"160,150,1",false,"50,0,1",false,false,false,false,false,false,false,false,1838,865,387,1047,708,1810,2700,1047,708,1810,1111,0},h)g[405202]=b({e[11034],405202,1,4,281,"「『剣は心なり』と、父上はよくおっしゃっていた。\n剣は大義と理想のためにのみ抜くべき……それと同じように、剣士の心も善良さと正義感を有するべきだ。\n貴殿の心は、まさに拙者の迷いを払い得る光であり、善良と正義そのもの。\n貴殿のためであれば、拙者は決して退かぬ。」",200052,1,"deco/character/405202",302002,60,1962,935,386,32,392,3085,2636,124,627,2901,1261,2,4769,4077,2700,4114,8000,8000,8000,8000,6000,8000,8000,false,false,0},h)g[405301]=b({e[32057],405301,false,130,282,false,200053,false,"deco/character/xiaoyesiqiyu",302002,60,false,false,false,false,-70,"1",false,false,false,false,false,false,false,"160,200,0.98","-50,10,1",false,false,false,false,"-40,0,1","-30,0,1","xiaoyesiqiyu"},h)g[405302]=b({e[12057],405302,1,4,283,"「真実は幻想、愛は欲望。\n理想を追い求め、心血を注いで築き上げたこの世界へようこそ。\n読み終えたら、ぜひ感想を教えてくださいね。」",200053,1,"deco/character/xiaoyesiqiyu_0",302002,60,1,"xiaoyesiqiyu_0"},h)g[405303]=b({e[21057],405303,11,131,284,"「ん？　……ふふっ、こんな知る人ぞ知るような場所であなたに会えるなんて、私達、心が通じ合っているのかもしれませんね。それではご褒美に、このお菓子でもあげましょうか。」",200053,2,"deco/character/xiaoyesiqiyu_YY",false,false,false,false,1,false,false,false,false,false,false,"40,-180,1","xiaoyesiqiyu_yy"},h)g[405304]=b({e[17057],405304,2,83,285,"「波の音を聞いてインスピレーションを得ようと思ったのですが、あなたの視線は無視しにくいですね。\n……まあいいでしょう。夏の夜の風が運んできた物語を、一緒に聞きましょうか。」",200053,2,"deco/character/xiaoyesiqiyu_xr",false,false,false,false,false,false,false,"","xiaoyesiqiyu_xr"},h)g[405401]=b({e[46057],405401,false,132,286,false,200054,false,"deco/character/xiamier",302002,60,false,false,false,false,-40,"1",false,false,false,false,false,false,false,"70,340,1","-60,10,1","30,10,1",false,false,false,"-40,0,1",false,false,false,false,1863,812,407,1433,752,1213,2849,1433,752,1213,1024,"xiamier"},h)g[405402]=b({e[23034],405402,1,4,287,"「聴きたい曲はない？ それとも、即興で何か歌おうか。\n君が歩いてくるのを見た瞬間、急にメロディーが降ってきてね。\nきっと、ロマンチックな曲になると思うんだ。」",200054,1,"deco/character/xiamier_0",302002,60,1,false,false,false,false,false,false,false,false,false,"-112,0,1","-97,0,1",1976,870,426,785,812,2329,1964,785,812,2329,1031,false,false,false,false,false,false,false,false,false,false,false,false,"xiamier_0"},h)g[405403]=b({e[21034],405403,13,107,288,"「ここは貸切風呂のはずなんだけど……いや、僕が勘違いしていたのかもしれない。お騒がせしたお詫びに後で何か奢らせて。この温泉のたこ焼きは種類が豊富なことで有名でね。君好みのたこ焼きもあると思うんだ。」",200054,2,"deco/character/xiamier_WQ",false,false,false,false,false,false,false,false,false,false,false,"0,312,1",1835,885,444,835,169,2614,2525,835,606,2614,1261,false,false,false,false,false,false,false,false,false,false,false,false,"xiamier_wq"},h)g[405404]=b({e[46057],405404,12,133,289,"「はは……今まで何度も盛大な祝祭に参加してきたけど、今日のこのプライベートな場ほど緊張したことはないよ。僕の心の音楽、聴いてくれるかい？」",200054,2,"deco/character/xiamier_LF",false,false,1,false,false,false,false,"1",false,false,"-420,0,1","150,0,0.98","-420,0,1","-420,0,1","-80,0,1",false,false,false,false,false,false,false,false,false,false,false,2284,856,420,516,198,2773,2998,516,565,2773,1261,"xiamier_lf"},h)